for (const blog of BLOGS) {
  AR_MAP[blog.categoryEn] = blog.categoryAr;
  AR_MAP[blog.locationEn] = blog.locationAr;
  AR_MAP[blog.dateEn] = blog.dateAr;
  AR_MAP[blog.readTimeEn] = blog.readTimeAr;
  blog.badgesEn.forEach((b, i) => {
    if (blog.badgesAr[i]) AR_MAP[b] = blog.badgesAr[i];
  });
  AR_MAP[blog.titleEn] = blog.titleAr;
  AR_MAP[blog.metaTitleEn] = blog.metaTitleAr;
  AR_MAP[blog.excerptEn] = blog.excerptAr;
  AR_MAP[blog.featuredImageAltEn] = blog.featuredImageAltAr;
  AR_MAP[blog.inlineImage1AltEn] = blog.inlineImage1AltAr;
  AR_MAP[blog.inlineImage1CaptionEn] = blog.inlineImage1CaptionAr;
  AR_MAP[blog.inlineImage2AltEn] = blog.inlineImage2AltAr;
  AR_MAP[blog.inlineImage2CaptionEn] = blog.inlineImage2CaptionAr;
  AR_MAP[blog.quoteEn] = blog.quoteAr;
  AR_MAP[blog.quoteAuthorEn] = blog.quoteAuthorAr;
  AR_MAP[blog.ctaHeadingEn] = blog.ctaHeadingAr;
  AR_MAP[blog.ctaTextEn] = blog.ctaTextAr;
  AR_MAP[blog.ctaPrimaryLabelEn] = blog.ctaPrimaryLabelAr;
  AR_MAP[blog.ctaSecondaryLabelEn] = blog.ctaSecondaryLabelAr;
  for (const sec of blog.sections) {
    AR_MAP[sec.h2En] = sec.h2Ar;
    if (sec.bulletsEn && sec.bulletsAr) {
      sec.bulletsEn.forEach((item, i) => {
        if (sec.bulletsAr[i]) AR_MAP[item] = sec.bulletsAr[i];
      });
    }
    for (const p of sec.paragraphs) {
      if (p.en && p.ar) AR_MAP[p.en.trim()] = p.ar.trim();
      if (p.linkTextEn && p.linkTextAr) AR_MAP[p.linkTextEn.trim()] = p.linkTextAr.trim();
      if (p.afterEn && p.afterAr) AR_MAP[p.afterEn.trim()] = p.afterAr.trim();
      if (p.link2TextEn && p.link2TextAr) AR_MAP[p.link2TextEn.trim()] = p.link2TextAr.trim();
      if (p.after2En && p.after2Ar) AR_MAP[p.after2En.trim()] = p.after2Ar.trim();
      if (p.link3TextEn && p.link3TextAr) AR_MAP[p.link3TextEn.trim()] = p.link3TextAr.trim();
      if (p.after3En && p.after3Ar) AR_MAP[p.after3En.trim()] = p.after3Ar.trim();
    }
  }
}

